function parseSymptoms(text:string,lang:TriageLang){const lower=text.toLowerCase();return SYMPTOMS.filter(s=>s.keywords[lang].some(k=>lower.includes(k.toLowerCase())))}
function assessSymptoms(found:typeof SYMPTOMS){if(!found.length)return null;let top=found[0];found.forEach(s=>{if(s.severity>top.severity)top=s});const urgencyKey=top.severity>=3?'High':top.severity===2?'Medium':'Low';return {urgencyKey,specialty:top.specialty}}

export default function Page(){
 const [view,setView]=useState<View>('overview');const [dark,setDark]=useState(false);const [menuOpen,setMenuOpen]=useState(false);const [query,setQuery]=useState('');const [specialityFilter,setSpecialityFilter]=useState('All Specialties');const [locationType,setLocationType]=useState<LocationType>('Semi-urban');const [booked,setBooked]=useState<Doctor|null>(null);const [callDoctor,setCallDoctor]=useState<Doctor|null>(null);const [callSeconds,setCallSeconds]=useState(0);const [callConnected,setCallConnected]=useState(false);const [reminder,setReminder]=useState(false);const [threadShared,setThreadShared]=useState(false);const [briefOpen,setBriefOpen]=useState(false);const [aiFollowup,setAiFollowup]=useState(false);const [locationGranted,setLocationGranted]=useState(false);const [toast,setToast]=useState('');
 const filteredDoctors=useMemo(()=>doctors.filter(d=>`${d.name} ${d.speciality} ${d.location}`.toLowerCase().includes(query.toLowerCase().trim())&&(specialityFilter==='All Specialties'||d.speciality===specialityFilter)),[query,specialityFilter]);
 const navigate=(next:View,speciality?:string)=>{if(next==='doctors'&&speciality)setSpecialityFilter(speciality);setView(next);setMenuOpen(false);window.scrollTo({top:0,behavior:'smooth'})};
 const notify=async(message:string)=>{setToast(message);window.setTimeout(()=>setToast(''),3500);if(typeof Notification!=='undefined'){try{if(Notification.permission==='granted')new Notification('MedThread',{body:message});else if(Notification.permission!=='denied')await Notification.requestPermission()}catch{}}};
 const openCall=(doctor:Doctor)=>{setCallDoctor(doctor);setCallSeconds(0);setCallConnected(false)};useEffect(()=>{if(!callDoctor||!callConnected)return;const id=window.setInterval(()=>setCallSeconds(s=>s+1),1000);return()=>window.clearInterval(id)},[callDoctor,callConnected]);const book=(doctor:Doctor)=>{setBooked(doctor);notify(`Appointment request saved for ${doctor.name} at ${doctor.availability}.`)};
 return <div className={dark?'dark min-h-screen':'min-h-screen'}><div className="min-h-screen bg-background text-foreground">
 <header className="sticky top-0 z-50 border-b border-border/70 bg-background/90 backdrop-blur-xl"><div className="mx-auto flex max-w-7xl items-center justify-between gap-4 px-5 py-3 lg:px-8"><button onClick={()=>navigate('overview')} className="flex items-center gap-2.5"><span className="grid size-10 place-items-center rounded-2xl bg-primary text-primary-foreground"><HeartPulse className="size-5"/></span><span className="font-display text-lg font-bold text-primary">MedThread<span className="text-accent">.</span></span></button><nav className="hidden items-center gap-1 lg:flex">{(['overview','doctors','triage','tests','packages','home-care'] as View[]).map(item=><button key={item} onClick={()=>navigate(item)} className={`rounded-full px-3 py-2 text-sm font-semibold capitalize ${view===item?'bg-secondary text-primary':'text-muted-foreground hover:bg-secondary'}`}>{item==='overview'?'Overview':item==='triage'?'AI Triage':item.replace('-',' ')}</button>)}</nav><div className="flex items-center gap-2"><a href="/sos" className="grid size-10 place-items-center rounded-full border border-destructive/30 bg-destructive/10 text-destructive font-black text-[10px]">SOS</a><button onClick={()=>setDark(!dark)} className="grid size-10 place-items-center rounded-full border border-border bg-card text-primary">{dark?<Sun className="size-4"/>:<Moon className="size-4"/>}</button><a href="https://medthread-v2.vercel.app/" className="hidden items-center gap-2 rounded-full bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground sm:flex"><UserRound className="size-4"/>My care</a><button onClick={()=>setMenuOpen(!menuOpen)} className="grid size-10 place-items-center rounded-full border border-border lg:hidden">{menuOpen?<X/>:<Menu/>}</button></div></div>{menuOpen&&<nav className="flex flex-col border-t border-border px-5 py-3 lg:hidden">{(['overview','doctors','triage','tests','packages','home-care','medicines','thread','account'] as View[]).map(item=><button key={item} onClick={()=>navigate(item)} className="rounded-lg px-3 py-2 text-left text-sm font-semibold">{item==='triage'?'AI Triage':item.replace('-',' ')}</button>)}</nav>}</header>
 {view==='overview'&&<Overview navigate={navigate} locationType={locationType} setLocationType={setLocationType} locationGranted={locationGranted} setLocationGranted={setLocationGranted} reminder={reminder} setReminder={setReminder} aiFollowup={aiFollowup} setAiFollowup={setAiFollowup} threadShared={threadShared} setThreadShared={setThreadShared} openBrief={()=>setBriefOpen(true)}/>} {view==='doctors'&&<Doctors doctors={filteredDoctors} query={query} setQuery={setQuery} specialityFilter={specialityFilter} setSpecialityFilter={setSpecialityFilter} locationType={locationType} setLocationType={setLocationType} onBook={book} onCall={openCall} booked={booked}/>} {view==='triage'&&<Triage navigate={navigate}/>} {view==='tests'&&<Tests/>} {view==='packages'&&<Packages/>} {view==='home-care'&&<HomeCare/>} {view==='medicines'&&<Medicines reminder={reminder} setReminder={setReminder}/>} {view==='thread'&&<HealthThread threadShared={threadShared} setThreadShared={setThreadShared}/>} {view==='account'&&<Account/>}
 <section className="border-y border-border bg-secondary px-5 py-12 lg:px-8"><div className="mx-auto grid max-w-7xl items-center gap-8 lg:grid-cols-[1fr_auto]"><div><p className="eyebrow">MedThread in your pocket</p><h2 className="mt-3 font-display text-3xl font-bold">Download the Med Thread App</h2><p className="mt-4 max-w-xl text-muted-foreground">Keep your care timeline, reminders, reports, and trusted next steps close wherever your day takes you.</p><a href="https://claude.ai/public/artifacts/55927b98-a6f8-4822-817c-72ded678c940" target="_blank" rel="noreferrer" className="mt-6 inline-flex items-center gap-2 rounded-xl bg-primary px-5 py-3 font-bold text-primary-foreground">Open MedThread App <ArrowRight className="size-4"/></a></div><div className="hidden rounded-[2rem] border-8 border-primary bg-card p-3 shadow-2xl sm:block"><div className="rounded-[1.25rem] bg-primary p-6 text-primary-foreground"><HeartPulse className="size-7 text-accent"/><p className="mt-12 font-display font-bold">One Health Thread.</p><p className="mt-1 text-sm opacity-70">Care that stays with you.</p></div></div></div></section>
 <footer className="border-t border-border bg-card px-5 py-10 lg:px-8"><div className="mx-auto grid max-w-7xl gap-8 md:grid-cols-[1.4fr_1fr_1fr_1fr]"><div><p className="font-display text-lg font-bold text-primary">MedThread<span className="text-accent">.</span></p><p className="mt-3 max-w-xs text-sm leading-6 text-muted-foreground">Care that stays with you — for every Indian, in every corner.</p><p className="mt-5 flex items-center gap-2 text-xs text-muted-foreground"><ShieldCheck className="size-4 text-primary"/> Your care, private and secure</p></div>{[['Care','Find a doctor','Health Thread','Book a test'],['Support','Home care','Medicine reminders','SOS emergency'],['Company','About MedThread','Contact us','My care']].map(([heading,...links])=><div key={heading}><p className="text-sm font-bold">{heading}</p><div className="mt-3 flex flex-col items-start gap-2">{links.map(link=><button key={link} onClick={()=>link==='Find a doctor'?navigate('doctors'):link==='Health Thread'?navigate('thread'):link==='Book a test'?navigate('tests'):link==='Home care'?navigate('home-care'):link==='Medicine reminders'?navigate('medicines'):link==='SOS emergency'?window.location.assign('/sos'):link==='My care'?window.location.assign('https://medthread-v2.vercel.app/'):setToast(`${link} — demo information`)} className="text-sm text-muted-foreground hover:text-primary">{link}</button>)}</div></div>)}</div><div className="mx-auto mt-8 max-w-7xl border-t border-border pt-5 text-xs text-muted-foreground">© 2026 MedThread Health · Made for continuous care.</div></footer>
 {toast&&<div className="fixed bottom-5 left-1/2 z-[80] -translate-x-1/2 rounded-full bg-foreground px-5 py-3 text-sm font-semibold text-background shadow-2xl">{toast}</div>}
 {briefOpen&&<Modal title="Structured patient brief" onClose={()=>setBriefOpen(false)}><div className="space-y-3"><BriefRow label="Current symptoms" value="Fever · headache · body ache"/><BriefRow label="Current medicines" value="Metformin · Vitamin D3"/><BriefRow label="Relevant history" value="Previous prescriptions and recent blood-test results"/><div className="rounded-2xl bg-secondary p-4 text-sm leading-6 text-muted-foreground">This demo brief is assembled from the patient’s Health Thread so the next doctor can start with context instead of repeating the whole story.</div><button onClick={()=>{setBriefOpen(false);notify('Patient brief shared with the selected care pathway.')}} className="w-full rounded-xl bg-primary px-4 py-3 font-bold text-primary-foreground">Continue with this brief</button></div></Modal>}
 {booked&&<Modal title="Appointment requested" onClose={()=>setBooked(null)}><div className="rounded-2xl bg-secondary p-5"><p className="font-display text-xl font-bold">{booked.name}</p><p className="mt-1 text-primary font-semibold">{booked.speciality}</p><div className="mt-4 space-y-2 text-sm text-muted-foreground"><p>📅 {booked.availability}</p><p>📍 {booked.location}</p><p>💳 {booked.fee}</p></div></div><button onClick={()=>{setReminder(true);setBooked(null);notify('Appointment reminder enabled.')}} className="mt-4 w-full rounded-xl bg-primary px-4 py-3 font-bold text-primary-foreground">Turn on appointment reminder</button><button onClick={()=>setBooked(null)} className="mt-2 w-full rounded-xl border border-border px-4 py-3 font-bold">Close</button></Modal>}
 {callDoctor&&<DoctorCall doctor={callDoctor} connected={callConnected} seconds={callSeconds} onAccept={()=>setCallConnected(true)} onDecline={()=>setCallDoctor(null)} onEnd={()=>{const n=callDoctor.name;setCallDoctor(null);setCallConnected(false);notify(`Call summary saved for ${n}.`)}}/>}
 </div></div>
}

function Overview({navigate,locationType,setLocationType,locationGranted,setLocationGranted,reminder,setReminder,aiFollowup,setAiFollowup,threadShared,setThreadShared,openBrief}:{navigate:(v:View,s?:string)=>void;locationType:LocationType;setLocationType:(v:LocationType)=>void;locationGranted:boolean;setLocationGranted:(v:boolean)=>void;reminder:boolean;setReminder:(v:boolean)=>void;aiFollowup:boolean;setAiFollowup:(v:boolean)=>void;threadShared:boolean;setThreadShared:(v:boolean)=>void;openBrief:()=>void}){return <main><section className="relative overflow-hidden bg-primary text-primary-foreground"><div className="absolute inset-0 dot-grid opacity-20"/><div className="relative mx-auto grid max-w-7xl items-center gap-12 px-5 py-16 lg:grid-cols-[1.1fr_.9fr] lg:px-8 lg:py-24"><div><p className="mb-5 inline-flex rounded-full border border-primary-foreground/20 bg-primary-foreground/10 px-3 py-1.5 text-xs font-bold uppercase tracking-widest">AI-assisted connected care</p><h1 className="max-w-3xl font-display text-4xl font-bold leading-[1.05] sm:text-6xl">One Health Thread. <span className="text-accent">Every step.</span></h1><p className="mt-6 max-w-xl text-lg leading-8 text-primary-foreground/75">From symptoms and prescriptions to medicine alerts, AI follow-ups, local doctors, referrals, and reports — your care journey stays connected.</p><div className="mt-8 flex flex-wrap gap-3"><button onClick={()=>navigate('doctors')} className="inline-flex items-center gap-2 rounded-full bg-accent px-5 py-3.5 font-bold text-accent-foreground">Find a doctor <ArrowRight className="size-4"/></button><button onClick={()=>navigate('triage')} className="inline-flex items-center gap-2 rounded-full border border-primary-foreground/25 px-5 py-3.5 font-bold">Try AI triage <Mic className="size-4"/></button></div></div><div className="rounded-[2rem] border border-primary-foreground/20 bg-primary-foreground/10 p-5 backdrop-blur"><div className="flex items-center justify-between"><div><p className="text-xs uppercase tracking-widest opacity-60">Today’s Health Thread</p><p className="mt-1 text-xl font-bold">Priya’s care journey</p></div><HeartPulse className="text-accent"/></div><div className="mt-5 space-y-3">{threadItems.map(item=><div key={item.title} className="flex items-center gap-3 rounded-2xl bg-background p-3 text-foreground"><span className="grid size-10 place-items-center rounded-xl bg-secondary text-primary"><item.icon className="size-4"/></span><div className="flex-1"><p className="text-sm font-bold">{item.title}</p><p className="text-xs text-muted-foreground">{item.detail}</p></div><span className="text-[10px] text-muted-foreground">{item.time}</span></div>)}</div></div></div></section><section className="mx-auto max-w-7xl px-5 py-12 lg:px-8"><div className="grid gap-4 lg:grid-cols-3"><article className="rounded-3xl border border-border bg-card p-6 lg:col-span-2"><div className="flex flex-wrap items-center justify-between gap-4"><div><p className="eyebrow">Care pathway</p><h2 className="mt-2 font-display text-2xl font-bold">Where are you getting care?</h2><p className="mt-2 text-sm text-muted-foreground">MedThread adapts the starting point to the patient’s local context.</p></div><MapPinned className="size-7 text-primary"/></div><div className="mt-5 grid gap-2 sm:grid-cols-3">{(['Rural','Semi-urban','Metro'] as LocationType[]).map(item=><button key={item} onClick={()=>setLocationType(item)} className={`rounded-2xl border p-4 text-left ${locationType===item?'border-primary bg-secondary':'border-border'}`}><p className="font-bold">{item}</p><p className="mt-1 text-xs text-muted-foreground">{item==='Rural'?'PHC + teleconsult':item==='Semi-urban'?'Local doctor + referral':'Specialist network'}</p></button>)}</div><div className="mt-5 rounded-2xl bg-secondary p-4"><div className="flex items-start gap-3"><Navigation className="mt-1 size-5 text-primary"/><div className="flex-1"><p className="font-bold">{locationType==='Rural'?'Nearest verified care point':locationType==='Semi-urban'?'Local doctor first, specialist when needed':'Choose a trusted specialist nearby'}</p><p className="mt-1 text-sm leading-6 text-muted-foreground">{locationType==='Rural'?'Find a nearby PHC or available teleconsultation.':locationType==='Semi-urban'?'Keep the local consultation connected to a specialist referral.':'Search doctors by specialty, location, language, and consultation mode.'}</p></div></div><button onClick={()=>{setLocationGranted(true);navigate('doctors')}} className="mt-4 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground">{locationGranted?'Use my local doctor network':'Use my location & find care'}</button></div></article><article className="rounded-3xl bg-secondary p-6"><Sparkles className="size-6 text-primary"/><h3 className="mt-5 font-display text-xl font-bold">Doctor-ready patient brief</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Symptoms, current medicines, prescriptions, reports, and history are organized before the consultation.</p><button onClick={openBrief} className="mt-6 w-full rounded-xl bg-primary px-4 py-3 text-sm font-bold text-primary-foreground">View structured brief</button></article></div><div className="mt-8 grid gap-4 md:grid-cols-3"><article className="rounded-3xl border border-border bg-card p-5"><Pill className="text-primary"/><h3 className="mt-5 font-display font-bold">Medicine schedule alert</h3><p className="mt-2 text-sm text-muted-foreground">Keep medication reminders visible and timely.</p><button onClick={()=>setReminder(!reminder)} className="mt-5 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground">{reminder?'Reminder on':'Turn reminder on'}</button></article><article className="rounded-3xl border border-border bg-card p-5"><PhoneIncoming className="text-primary"/><h3 className="mt-5 font-display font-bold">AI follow-up calls</h3><p className="mt-2 text-sm text-muted-foreground">Demo follow-up for adherence and symptom check-ins.</p><button onClick={()=>setAiFollowup(!aiFollowup)} className="mt-5 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground">{aiFollowup?'Follow-up scheduled':'Schedule AI follow-up'}</button></article><article className="rounded-3xl border border-border bg-card p-5"><Share2 className="text-primary"/><h3 className="mt-5 font-display font-bold">Consent-based sharing</h3><p className="mt-2 text-sm text-muted-foreground">Share relevant Health Thread context with a specialist only when you choose.</p><button onClick={()=>setThreadShared(!threadShared)} className="mt-5 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground">{threadShared?'Sharing enabled':'Share with consent'}</button></article></div></section></main>}

function Doctors({doctors,query,setQuery,specialityFilter,setSpecialityFilter,locationType,setLocationType,onBook,onCall,booked}:{doctors:Doctor[];query:string;setQuery:(v:string)=>void;specialityFilter:string;setSpecialityFilter:(v:string)=>void;locationType:LocationType;setLocationType:(v:LocationType)=>void;onBook:(d:Doctor)=>void;onCall:(d:Doctor)=>void;booked:Doctor|null}){return <PageShell eyebrow="Find a doctor" title="Choose a doctor you trust, close to you." description="Start with your local region, then choose the doctor, specialty, consultation mode, and time that work for you."><div className="rounded-3xl bg-secondary p-5"><div className="flex flex-wrap items-center justify-between gap-4"><div><p className="font-bold">Your care context</p><p className="mt-1 text-sm text-muted-foreground">{locationType} pathway · local Varanasi network</p></div><div className="flex flex-wrap gap-2">{(['Rural','Semi-urban','Metro'] as LocationType[]).map(item=><button key={item} onClick={()=>setLocationType(item)} className={`rounded-full px-3 py-2 text-xs font-bold ${locationType===item?'bg-primary text-primary-foreground':'bg-card'}`}>{item}</button>)}</div></div></div><div className="mt-5 grid gap-3 md:grid-cols-[1fr_auto]"><div className="relative"><Search className="absolute left-4 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search doctor, specialty or local area" className="h-12 w-full rounded-2xl border border-border bg-card pl-11 pr-4 outline-none"/></div><select value={specialityFilter} onChange={e=>setSpecialityFilter(e.target.value)} className="h-12 rounded-2xl border border-border bg-card px-4 text-sm font-semibold">{SPECIALTIES.map(s=><option key={s}>{s}</option>)}</select></div><p className="mt-4 text-sm text-muted-foreground">Showing <strong className="text-foreground">{doctors.length}</strong> trusted local doctors</p><div className="mt-6 grid gap-4 lg:grid-cols-3">{doctors.map(doctor=><article key={doctor.name} className="rounded-3xl border border-border bg-card p-5 shadow-sm"><div className="flex items-start justify-between"><div className={`grid size-14 place-items-center rounded-2xl text-lg font-bold text-primary-foreground ${doctor.tone}`}>{doctor.initials}</div><span className="flex items-center gap-1 rounded-full bg-secondary px-2.5 py-1 text-xs font-bold text-primary"><Star className="size-3 fill-current"/>{doctor.rating}</span></div><h3 className="mt-5 font-display font-bold">{doctor.name}</h3><p className="mt-1 text-sm font-semibold text-primary">{doctor.speciality}</p><p className="mt-3 flex items-center gap-2 text-sm text-muted-foreground"><MapPin className="size-4"/>{doctor.meta}</p><div className="mt-4 grid grid-cols-2 gap-2 text-xs"><div className="rounded-xl bg-secondary p-3"><p className="font-bold">Experience</p><p className="mt-1 text-muted-foreground">{doctor.experience}</p></div><div className="rounded-xl bg-secondary p-3"><p className="font-bold">Languages</p><p className="mt-1 text-muted-foreground">{doctor.languages}</p></div></div><p className="mt-4 text-xs leading-5 text-muted-foreground">{doctor.bio}</p><p className="mt-3 text-xs text-muted-foreground"><strong className="text-foreground">Next:</strong> {doctor.availability} · {doctor.fee}</p><div className="mt-5 grid grid-cols-2 gap-2"><button onClick={()=>onCall(doctor)} className="inline-flex items-center justify-center gap-2 rounded-xl border border-primary px-3 py-3 text-sm font-bold text-primary"><PhoneCall className="size-4"/>Call doctor</button><button onClick={()=>onBook(doctor)} className="inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-3 py-3 text-sm font-bold text-primary-foreground">{booked?.name===doctor.name?<Check className="size-4"/>:null}{booked?.name===doctor.name?'Booked':'Book'}</button></div><button onClick={()=>window.alert(`Patient rating: ${doctor.rating}/5\nLocal patients can review this doctor after consultation.`)} className="mt-2 w-full rounded-xl bg-secondary px-3 py-2.5 text-xs font-bold text-primary">View patient reviews</button></article>)}</div></PageShell>}

function Triage({navigate}:{navigate:(v:View,s?:string)=>void}){const [lang,setLang]=useState<TriageLang>('en');const [state,setState]=useState<'idle'|'listening'|'processing'|'done'|'error'>('idle');const [transcript,setTranscript]=useState('');const [found,setFound]=useState<typeof SYMPTOMS>([]);const [assessment,setAssessment]=useState<ReturnType<typeof assessSymptoms>>(null);const [errorMsg,setErrorMsg]=useState('');const [manualText,setManualText]=useState('');const recogRef=useRef<any>(null);const S=TRIAGE_STRINGS[lang];
 useEffect(()=>()=>{if(recogRef.current){try{recogRef.current.stop()}catch{}}},[]);
 const runAnalysis=(text:string)=>{const f=parseSymptoms(text,lang);setFound(f);setAssessment(assessSymptoms(f));setState('done')};
 const startListening=()=>{if(state==='listening'){try{recogRef.current?.stop()}catch{};return}const SR=(window as any).SpeechRecognition||(window as any).webkitSpeechRecognition;if(!SR){setErrorMsg(S.notSupported);setState('error');return}const recog=new SR();recog.lang=TRIAGE_LANGS.find(l=>l.id===lang)!.code;recog.interimResults=false;recog.maxAlternatives=1;recog.onstart=()=>{setState('listening');setErrorMsg('')};recog.onresult=(ev:any)=>{const text=ev.results[0][0].transcript;setTranscript(text);setState('processing');window.setTimeout(()=>runAnalysis(text),500)};recog.onerror=(ev:any)=>{const msg=['not-allowed','permission-denied','service-not-allowed'].includes(ev.error)?S.micDenied:S.noSpeech;setErrorMsg(msg);setState('error')};recog.onend=()=>setState(cur=>cur==='listening'?'idle':cur);recogRef.current=recog;try{recog.start()}catch{setErrorMsg(S.noSpeech);setState('error')}};
 const reset=()=>{setState('idle');setTranscript('');setFound([]);setAssessment(null);setErrorMsg('');setManualText('')};const handleManualAnalyze=()=>{if(!manualText.trim())return;setTranscript(manualText.trim());runAnalysis(manualText.trim())};
 return <PageShell eyebrow="AI triage" title={S.heading} description="Speak or type symptoms in your own words. This demo provides care-navigation guidance, not a diagnosis."><div className="mb-5 flex w-fit rounded-full border border-border bg-card p-1">{TRIAGE_LANGS.map(l=><button key={l.id} onClick={()=>{setLang(l.id);reset()}} className={`rounded-full px-4 py-2 text-sm font-bold transition ${lang===l.id?'bg-primary text-primary-foreground':'text-muted-foreground hover:bg-secondary'}`}>{l.label}</button>)}</div><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div className="rounded-[2rem] border border-border bg-card p-7"><button onClick={startListening} className={`mx-auto grid size-28 place-items-center rounded-full text-primary-foreground shadow-xl transition ${state==='listening'?'bg-accent':'bg-primary hover:scale-105'}`} aria-label={S.heading}>{state==='listening'||state==='processing'?<Loader2 className="size-9 animate-spin"/>:<Mic className="size-9"/>}</button><p className="mt-5 text-center font-bold">{state==='idle'&&S.heading}{state==='listening'&&S.listening}{state==='processing'&&S.processing}{state==='done'&&S.heard}{state==='error'&&S.heading}</p><p className="mt-1 text-center text-sm text-muted-foreground">{state==='idle'&&S.sub}{state==='listening'&&S.listeningSub}{state==='error'&&errorMsg}</p>{state==='done'&&<div className="mt-4 rounded-2xl bg-secondary p-4 text-sm">“{transcript}”</div>}{(state==='idle'||state==='error')&&<div className="mt-6"><textarea value={manualText} onChange={e=>setManualText(e.target.value)} placeholder={S.typePlaceholder} rows={3} className="w-full rounded-2xl border border-border bg-background p-4 outline-none focus:border-primary"/><div className="mt-2 flex items-center justify-between gap-3"><span className="text-xs text-muted-foreground">{S.orType}</span><button onClick={handleManualAnalyze} disabled={!manualText.trim()} className="rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground disabled:opacity-40">{S.analyze} <ArrowRight className="ml-1 inline size-4"/></button></div></div>}</div><aside className="rounded-[2rem] bg-primary p-7 text-primary-foreground"><ShieldCheck className="size-7 text-accent"/>{!found.length?<><h2 className="mt-5 font-display text-2xl font-bold">Right next step</h2><p className="mt-5 text-sm leading-7 text-primary-foreground/75">Your result will connect directly to the doctor directory and specialty filter.</p></>:<><div className="mt-5 space-y-4"><div><p className="text-xs uppercase tracking-wider opacity-60">{S.symptoms}</p><div className="mt-2 flex flex-wrap gap-2">{found.map(f=><span key={f.id} className="rounded-full bg-primary-foreground/10 px-3 py-1.5 text-sm font-semibold">{f.label[lang]}</span>)}</div></div><div className="flex items-center justify-between border-t border-primary-foreground/10 pt-4"><span>{S.urgency}</span><strong className="text-accent">{S.urgencyLabels[assessment!.urgencyKey]}</strong></div><div className="flex items-center justify-between border-t border-primary-foreground/10 pt-4"><span>{S.recommended}</span><strong>{(SPECIALTY_LABELS[assessment!.specialty]||{en:assessment!.specialty,hi:assessment!.specialty,bn:assessment!.specialty})[lang]}</strong></div><button onClick={()=>navigate('doctors',assessment!.specialty)} className="w-full rounded-xl bg-accent px-4 py-3 font-bold text-accent-foreground">{S.findDoctor} <ArrowRight className="ml-1 inline size-4"/></button><button onClick={reset} className="text-sm font-bold text-primary-foreground/75"><RotateCcw className="mr-1 inline size-4"/>{S.tryAgain}</button></div></>}<p className="mt-7 text-xs leading-5 text-primary-foreground/55">For severe or urgent symptoms, contact local emergency services.</p></aside></div></PageShell>}

function HealthThread({threadShared,setThreadShared}:{threadShared:boolean;setThreadShared:(v:boolean)=>void}){return <PageShell eyebrow="Health Thread" title="Your history travels with you." description="Prescriptions, reports, medicines, reminders, and follow-ups stay connected in one patient timeline."><div className="grid gap-4 lg:grid-cols-[1fr_.8fr]"><div className="space-y-3">{threadItems.map(item=><article key={item.title} className="flex items-center gap-4 rounded-3xl border border-border bg-card p-5"><span className="grid size-12 place-items-center rounded-2xl bg-secondary text-primary"><item.icon className="size-5"/></span><div className="flex-1"><p className="text-xs font-bold uppercase tracking-wider text-primary">{item.type}</p><h3 className="mt-1 font-display font-bold">{item.title}</h3><p className="mt-1 text-sm text-muted-foreground">{item.detail}</p></div><span className="text-xs text-muted-foreground">{item.time}</span></article>)}</div><aside className="rounded-3xl bg-primary p-6 text-primary-foreground"><Share2 className="text-accent"/><h3 className="mt-5 font-display text-xl font-bold">Specialist referral sharing</h3><p className="mt-2 text-sm leading-6 text-primary-foreground/75">With patient consent, share relevant prescriptions, reports, current medicines, and medical history with the specialist.</p><button onClick={()=>setThreadShared(!threadShared)} className="mt-6 w-full rounded-xl bg-accent px-4 py-3 font-bold text-accent-foreground">{threadShared?'Consent recorded':'Give consent & share relevant thread'}</button>{threadShared&&<p className="mt-3 text-xs text-primary-foreground/70">Demo status: relevant Health Thread context is ready for the specialist.</p>}</aside></div></PageShell>}
function Tests(){
  const [priceFilter,setPriceFilter]=useState('All')
  const [selected,setSelected]=useState<any>(null)
  const tests=[
    {title:'Complete Blood Count (CBC)',category:'Blood',price:249,detail:'Screens blood-cell counts and related indices.',sample:'Blood',prep:'No special preparation usually required.',reports:'Same day / next day',items:['Haemoglobin','RBC count','WBC count','Platelet count','RBC indices','Differential count']},
    {title:'Fasting Blood Sugar (FBS)',category:'Diabetes',price:99,detail:'Measures blood glucose after an overnight fast.',sample:'Blood',prep:'Usually 8–12 hours fasting; water is generally allowed.',reports:'Same day',items:['Fasting plasma glucose']},
    {title:'HbA1c',category:'Diabetes',price:299,detail:'Estimates average blood-glucose control over the previous few months.',sample:'Blood',prep:'No fasting usually required.',reports:'Same day / next day',items:['Glycated haemoglobin (HbA1c)']},
    {title:'Lipid Profile',category:'Heart',price:399,detail:'Measures cholesterol and triglycerides used in cardiovascular risk assessment.',sample:'Blood',prep:'Fasting may be advised by the lab depending on the panel.',reports:'Same day / next day',items:['Total cholesterol','HDL','LDL','Triglycerides','VLDL / calculated ratios where applicable']},
    {title:'Liver Function Test (LFT)',category:'Liver',price:399,detail:'Assesses common markers of liver function and injury.',sample:'Blood',prep:'Follow the laboratory instructions; fasting may be requested.',reports:'Same day / next day',items:['Bilirubin','ALT/SGPT','AST/SGOT','ALP','Total protein','Albumin']},
    {title:'Kidney Function Test (KFT)',category:'Kidney',price:449,detail:'Assesses kidney-related markers and electrolyte balance.',sample:'Blood',prep:'Follow the laboratory instructions.',reports:'Same day / next day',items:['Creatinine','Urea/BUN','Uric acid where included','Electrolytes where included','eGFR where applicable']},
    {title:'Thyroid Profile',category:'Thyroid',price:399,detail:'Measures the main thyroid hormones used for thyroid assessment.',sample:'Blood',prep:'Usually no fasting required.',reports:'Same day / next day',items:['T3','T4','TSH']},
    {title:'Vitamin D',category:'Vitamins',price:549,detail:'Measures circulating 25-hydroxy vitamin D levels.',sample:'Blood',prep:'Usually no fasting required.',reports:'1–2 days',items:['25-OH Vitamin D']},
    {title:'Vitamin B12',category:'Vitamins',price:449,detail:'Measures vitamin B12 status and may be used when deficiency is suspected.',sample:'Blood',prep:'Usually no fasting required.',reports:'1–2 days',items:['Serum Vitamin B12']},
    {title:'Iron Profile',category:'Nutrition',price:499,detail:'Looks at common blood markers related to iron status.',sample:'Blood',prep:'Follow lab instructions; morning/fasting collection may be preferred.',reports:'Same day / next day',items:['Serum iron','TIBC / transferrin-related marker','Transferrin saturation','Ferritin when included']},
    {title:'Urine Routine & Microscopy',category:'Urine',price:149,detail:'Screens urine for common physical, chemical and microscopic findings.',sample:'Urine',prep:'Clean-catch midstream sample is commonly requested.',reports:'Same day',items:['Appearance','pH','Protein','Glucose','Ketones','Blood','Microscopy / cells and deposits']},
    {title:'ESR',category:'Inflammation',price:199,detail:'A non-specific marker that can support evaluation of inflammation.',sample:'Blood',prep:'Usually no special preparation.',reports:'Same day',items:['Erythrocyte sedimentation rate']},
    {title:'CRP',category:'Inflammation',price:299,detail:'Measures C-reactive protein, a marker associated with inflammation.',sample:'Blood',prep:'Usually no special preparation.',reports:'Same day / next day',items:['C-reactive protein']},
    {title:'Calcium',category:'Nutrition',price:249,detail:'Measures calcium in the blood and is interpreted with clinical context.',sample:'Blood',prep:'Usually no special preparation.',reports:'Same day',items:['Total serum calcium']},
    {title:'Electrolytes Panel',category:'Kidney',price:349,detail:'Measures key electrolytes involved in fluid and metabolic balance.',sample:'Blood',prep:'Follow laboratory instructions.',reports:'Same day',items:['Sodium','Potassium','Chloride','Bicarbonate / total CO2 where included']},
    {title:'Full Body Basic Screen',category:'Preventive',price:699,detail:'A budget-friendly preventive screen combining commonly requested blood and urine checks.',sample:'Blood + urine',prep:'Fasting may be required depending on the final panel.',reports:'Same day / next day',items:['CBC','Fasting blood sugar','Lipid profile','LFT','KFT','Thyroid profile','Urine routine']},
    {title:'Fever Screening Panel',category:'Fever',price:549,detail:'A demo fever-focused bundle with common screening investigations; exact tests should be selected by a clinician/lab.',sample:'Blood',prep:'Follow lab instructions.',reports:'Same day / next day',items:['CBC','CRP','Malaria testing when clinically indicated','Dengue testing when clinically indicated']},
    {title:'Women’s Wellness Screen',category:'Women',price:799,detail:'A preventive women’s-health screening bundle for discussion with a clinician.',sample:'Blood + urine',prep:'Panel-specific preparation applies.',reports:'1–2 days',items:['CBC','Glucose screening','Thyroid profile','Lipid profile','Urine routine','Iron / vitamin markers where included']},
    {title:'Senior Wellness Screen',category:'Senior',price:899,detail:'A broader preventive screen designed around common age-related monitoring needs.',sample:'Blood + urine',prep:'Fasting may be required.',reports:'1–2 days',items:['CBC','Glucose + HbA1c','Lipid profile','LFT','KFT + electrolytes','Thyroid profile','Urine routine','Vitamin D / B12 where included']},
  ]
  const filters=['All','Under ₹300','₹300–₹500','₹500–₹800','Above ₹800']
  const visible=tests.filter(t=>priceFilter==='All'||(priceFilter==='Under ₹300'&&t.price<300)||(priceFilter==='₹300–₹500'&&t.price>=300&&t.price<=500)||(priceFilter==='₹500–₹800'&&t.price>500&&t.price<=800)||(priceFilter==='Above ₹800'&&t.price>800))
  return <PageShell eyebrow="Tests & reports" title="Diagnostics that stay in your thread." description="Browse individual tests and affordable screening bundles. Open any card to see what is included, sample type, preparation, and expected reporting time."><div className="mb-5 flex flex-wrap gap-2">{filters.map(f=><button key={f} onClick={()=>setPriceFilter(f)} className={`rounded-full border px-4 py-2 text-sm font-bold ${priceFilter===f?'border-primary bg-primary text-primary-foreground':'border-border bg-card text-muted-foreground hover:border-primary/40'}`}>{f}</button>)}</div><p className="mb-5 text-sm text-muted-foreground">Showing {visible.length} of {tests.length} demo diagnostics · Prices are illustrative MedThread demo pricing and may vary by lab/location.</p><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{visible.map(t=><article key={t.title} className="rounded-3xl border border-border bg-card p-5"><div className="flex items-start justify-between gap-3"><span className="grid size-11 place-items-center rounded-2xl bg-secondary text-primary"><TestTube2 className="size-5"/></span><span className="rounded-full bg-secondary px-2.5 py-1 text-xs font-bold text-primary">{t.category}</span></div><h3 className="mt-5 font-display font-bold">{t.title}</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{t.detail}</p><div className="mt-5 flex items-end justify-between gap-3"><div><p className="text-xs text-muted-foreground">Demo price</p><strong className="font-display text-xl text-primary">₹{t.price}</strong></div><div className="flex gap-2"><button onClick={()=>setSelected(t)} className="rounded-xl border border-border px-3 py-2 text-sm font-bold">Details</button><button onClick={()=>window.alert(`${t.title} added to your demo care journey.`)} className="rounded-xl bg-primary px-3 py-2 text-sm font-bold text-primary-foreground">Book</button></div></div></article>)}</div>{selected&&<Modal title={selected.title} onClose={()=>setSelected(null)}><div className="space-y-4"><p className="text-sm leading-6 text-muted-foreground">{selected.detail}</p><div className="grid gap-3 sm:grid-cols-2"><div className="rounded-2xl bg-secondary p-4"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Sample</p><p className="mt-1 font-bold">{selected.sample}</p></div><div className="rounded-2xl bg-secondary p-4"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Preparation</p><p className="mt-1 text-sm font-semibold">{selected.prep}</p></div><div className="rounded-2xl bg-secondary p-4"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Expected report</p><p className="mt-1 font-bold">{selected.reports}</p></div><div className="rounded-2xl bg-secondary p-4"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Demo price</p><p className="mt-1 font-display text-xl font-bold text-primary">₹{selected.price}</p></div></div><div><p className="text-sm font-bold">Included tests / markers</p><ul className="mt-2 grid gap-2 sm:grid-cols-2">{selected.items.map((item:string)=><li key={item} className="rounded-xl border border-border px-3 py-2 text-sm">✓ {item}</li>)}</ul></div><p className="text-xs leading-5 text-muted-foreground">This is a demonstration catalog, not medical advice. Exact test composition, fasting requirements, turnaround time, and interpretation depend on the laboratory and clinical context.</p><button onClick={()=>{window.alert(`${selected.title} added to your demo care journey.`);setSelected(null)}} className="w-full rounded-xl bg-primary px-4 py-3 font-bold text-primary-foreground">Book this test</button></div></Modal>}</PageShell>
}

function Packages(){
  const [priceFilter,setPriceFilter]=useState('All')
  const [selected,setSelected]=useState<any>(null)
  const packages=[
    {title:'Essential Health Screen',category:'Preventive',price:599,members:'1 member',detail:'Affordable baseline screening for everyday preventive care.',items:['CBC','Fasting blood sugar','Lipid profile','LFT','Urine routine'],prep:'Fasting may be required.',reports:'Same day / next day'},
    {title:'Diabetes Care',category:'Diabetes',price:699,members:'1 member',detail:'Budget-friendly glucose monitoring package.',items:['Fasting blood sugar','HbA1c','Kidney function markers','Urine routine'],prep:'Fasting may be required.',reports:'Same day / next day'},
    {title:'Thyroid & Wellness',category:'Thyroid',price:599,members:'1 member',detail:'Thyroid-focused screening with common wellness markers.',items:['T3','T4','TSH','CBC','Vitamin B12 where included'],prep:'Usually no fasting required.',reports:'Same day / next day'},
    {title:'Heart Health Starter',category:'Heart',price:799,members:'1 member',detail:'Entry-level cardiovascular risk screening.',items:['Lipid profile','Fasting blood sugar','HbA1c','CBC','CRP'],prep:'Fasting may be advised.',reports:'Same day / next day'},
    {title:'Gut & Digestive Screen',category:'Digestive',price:749,members:'1 member',detail:'Digestive-health screening bundle for discussion with a clinician.',items:['CBC','LFT','Amylase / lipase where included','CRP','Urine routine'],prep:'Panel-specific preparation applies.',reports:'1–2 days'},
    {title:'Family 2 Preventive',category:'Family',price:1199,members:'2 members',detail:'Two-person preventive screening at a lower combined demo price.',items:['CBC','Glucose screening','Lipid profile','LFT','KFT','Thyroid profile','Urine routine for each member'],prep:'Fasting may be required for some tests.',reports:'1–2 days'},
    {title:'Family 4 Full Wellness',category:'Family',price:2199,members:'4 members',detail:'A budget-oriented family screening bundle with broad preventive coverage.',items:['CBC','Glucose + HbA1c','Lipid profile','LFT','KFT + electrolytes','Thyroid profile','Urine routine','Vitamin D / B12 options'],prep:'Fasting may be required.',reports:'1–2 days'},
    {title:'Women’s Wellness Plus',category:'Women',price:999,members:'1 member',detail:'Broader women’s wellness screening for preventive care discussions.',items:['CBC','Lipid profile','Glucose screening','Thyroid profile','Iron profile','Vitamin D','Urine routine'],prep:'Panel-specific preparation applies.',reports:'1–2 days'},
    {title:'Senior Care Essentials',category:'Senior',price:1299,members:'1 member',detail:'Expanded preventive screening for common monitoring needs in older adults.',items:['CBC','HbA1c','Lipid profile','LFT','KFT + electrolytes','Thyroid profile','Urine routine','Vitamin D + B12'],prep:'Fasting may be required.',reports:'1–2 days'},
    {title:'Complete Full Body',category:'Full body',price:1499,members:'1 member',detail:'Comprehensive demo package covering blood, metabolic, organ-function, thyroid and nutritional markers.',items:['CBC + ESR','Glucose + HbA1c','Lipid profile','LFT','KFT + electrolytes','Thyroid profile','Urine routine','Vitamin D','Vitamin B12','Iron profile'],prep:'Usually 8–12 hours fasting; follow lab instructions.',reports:'1–2 days'},
    {title:'Full Body Plus',category:'Full body',price:1899,members:'1 member',detail:'A wider preventive package with additional nutritional and inflammation markers.',items:['Everything in Complete Full Body','CRP','Calcium','Iron studies','Vitamin D','Vitamin B12','Additional metabolic markers where included'],prep:'Usually fasting; exact preparation is lab-specific.',reports:'1–2 days'},
    {title:'Family 4 Comprehensive',category:'Family',price:2999,members:'4 members',detail:'Broad family screening designed as a value-focused demo bundle.',items:['CBC','Glucose + HbA1c','Lipid profile','LFT','KFT + electrolytes','Thyroid profile','Urine routine','Vitamin D / B12 options for each member'],prep:'Fasting may be required.',reports:'1–2 days'},
  ]
  const filters=['All','Under ₹800','₹800–₹1,500','₹1,500–₹2,500','Above ₹2,500']
  const visible=packages.filter(p=>priceFilter==='All'||(priceFilter==='Under ₹800'&&p.price<800)||(priceFilter==='₹800–₹1,500'&&p.price>=800&&p.price<=1500)||(priceFilter==='₹1,500–₹2,500'&&p.price>1500&&p.price<=2500)||(priceFilter==='Above ₹2,500'&&p.price>2500))
  return <PageShell eyebrow="Care packages" title="Preventive care for the people you care about." description="Compare affordable demo packages by price, then open any package to see exactly which tests and markers are included."><div className="mb-5 flex flex-wrap gap-2">{filters.map(f=><button key={f} onClick={()=>setPriceFilter(f)} className={`rounded-full border px-4 py-2 text-sm font-bold ${priceFilter===f?'border-primary bg-primary text-primary-foreground':'border-border bg-card text-muted-foreground hover:border-primary/40'}`}>{f}</button>)}</div><p className="mb-5 text-sm text-muted-foreground">Showing {visible.length} of {packages.length} demo packages · Prices are intentionally kept affordable for the prototype and are not live lab quotes.</p><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{visible.map(p=><article key={p.title} className="rounded-3xl border border-border bg-card p-6"><div className="flex items-start justify-between gap-3"><span className="grid size-11 place-items-center rounded-2xl bg-secondary text-primary"><Users className="size-5"/></span><span className="rounded-full bg-secondary px-2.5 py-1 text-xs font-bold text-primary">{p.category}</span></div><h3 className="mt-5 font-display text-xl font-bold">{p.title}</h3><p className="mt-1 text-xs font-bold text-muted-foreground">{p.members}</p><p className="mt-3 text-sm leading-6 text-muted-foreground">{p.detail}</p><p className="mt-5 font-display text-2xl font-bold text-primary">₹{p.price}</p><div className="mt-5 flex gap-2"><button onClick={()=>setSelected(p)} className="flex-1 rounded-xl border border-border px-4 py-3 text-sm font-bold">View included tests</button><button onClick={()=>window.alert(`${p.title} selected for this demo.`)} className="rounded-xl bg-primary px-4 py-3 text-sm font-bold text-primary-foreground">Choose</button></div></article>)}</div>{selected&&<Modal title={selected.title} onClose={()=>setSelected(null)}><div className="space-y-4"><div className="rounded-2xl bg-secondary p-4"><p className="text-sm font-bold">{selected.members} · {selected.category}</p><p className="mt-1 font-display text-2xl font-bold text-primary">₹{selected.price}</p></div><p className="text-sm leading-6 text-muted-foreground">{selected.detail}</p><div><p className="text-sm font-bold">Included tests / markers</p><ul className="mt-2 grid gap-2 sm:grid-cols-2">{selected.items.map((item:string)=><li key={item} className="rounded-xl border border-border px-3 py-2 text-sm">✓ {item}</li>)}</ul></div><div className="grid gap-3 sm:grid-cols-2"><div className="rounded-2xl border border-border p-4"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Preparation</p><p className="mt-1 text-sm font-semibold">{selected.prep}</p></div><div className="rounded-2xl border border-border p-4"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Expected report</p><p className="mt-1 text-sm font-semibold">{selected.reports}</p></div></div><p className="text-xs leading-5 text-muted-foreground">Demo catalog only. Exact package composition and preparation should be confirmed with the diagnostic laboratory and clinician.</p><button onClick={()=>{window.alert(`${selected.title} selected for this demo.`);setSelected(null)}} className="w-full rounded-xl bg-primary px-4 py-3 font-bold text-primary-foreground">Choose this package</button></div></Modal>}</PageShell>
}

function HomeCare(){return <PageShell eyebrow="Home care" title="Care can come home." description="Coordinate support for recovery, nursing, physiotherapy, and everyday family care."><div className="grid gap-4 sm:grid-cols-2">{[['Nurse visit','Vitals, recovery support, and routine care',Users],['Physiotherapy','Recovery support at home',Activity],['Elder care check-in','A scheduled family care visit',HeartPulse],['Medicine support','Help coordinating medicine routines',Pill]].map(([title,detail,Icon])=><button key={title as string} onClick={()=>window.alert(`${title} request started in this demo.`)} className="rounded-3xl border border-border bg-card p-6 text-left hover:border-primary/40"><span className="grid size-12 place-items-center rounded-2xl bg-secondary text-primary"><Icon className="size-5"/></span><h3 className="mt-7 font-display font-bold">{title as string}</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{detail as string}</p><span className="mt-5 inline-flex gap-1 text-sm font-bold text-primary">Request support <ArrowRight className="size-4"/></span></button>)}</div></PageShell>}
function Medicines({reminder,setReminder}:{reminder:boolean;setReminder:(v:boolean)=>void}){return <PageShell eyebrow="Medicines" title="Stay on track, gently." description="Medicine schedules and alerts stay connected to the Health Thread."><div className="rounded-3xl border border-border bg-card p-6"><div className="flex items-center justify-between"><div><p className="text-sm font-bold text-primary">Today · 6 September</p><h3 className="mt-1 font-display text-xl font-bold">Two reminders left</h3></div><Pill className="text-primary"/></div><div className="mt-6 space-y-3">{[['Metformin','500 mg · After dinner','7:00 PM'],['Vitamin D3','1 capsule · With food','8:30 PM']].map(([name,detail,time])=><div key={name} className="flex items-center gap-3 rounded-2xl bg-secondary p-4"><Clock3 className="text-primary"/><div className="flex-1"><p className="font-bold">{name}</p><p className="text-sm text-muted-foreground">{detail}</p></div><strong className="text-sm text-primary">{time}</strong></div>)}</div><button onClick={()=>setReminder(!reminder)} className="mt-5 w-full rounded-xl bg-primary px-4 py-3 font-bold text-primary-foreground">{reminder?'Medicine alerts are on':'Turn on medicine schedule alert'}</button></div></PageShell>}
function Account(){return <PageShell eyebrow="My care" title="One place for your care journey." description="Sign in to the connected care experience for appointments, reports, prescriptions, and follow-ups."><div className="grid gap-4 sm:grid-cols-2">{[['Health Thread','Prescriptions, reports, medicines, follow-ups',FileText],['Appointments','Upcoming and past consultations',CalendarDays],['AI follow-ups','Adherence and symptom check-ins',PhoneIncoming],['Family','Care for the people you trust',Users]].map(([title,detail,Icon])=><div key={title as string} className="rounded-3xl border border-border bg-card p-5"><Icon className="text-primary"/><h3 className="mt-5 font-display font-bold">{title as string}</h3><p className="mt-2 text-sm text-muted-foreground">{detail as string}</p></div>)}</div><a href="https://medthread-v2.vercel.app/" className="mt-6 inline-flex rounded-xl bg-primary px-5 py-3 font-bold text-primary-foreground">Open secure My care</a></PageShell>}
function DoctorCall({doctor,connected,seconds,onAccept,onDecline,onEnd}:{doctor:Doctor;connected:boolean;seconds:number;onAccept:()=>void;onDecline:()=>void;onEnd:()=>void}){return <div className="fixed inset-0 z-[90] grid place-items-center bg-foreground/70 p-5"><div className="w-full max-w-md rounded-[2rem] bg-card p-7 text-center shadow-2xl"><div className={`mx-auto grid size-24 place-items-center rounded-full ${connected?'bg-primary':'bg-secondary'} text-primary-foreground`}><PhoneCall className="size-9"/></div><p className="mt-5 text-xs font-bold uppercase tracking-widest text-muted-foreground">{connected?'Connected':'Incoming demo call'}</p><h2 className="mt-2 font-display text-2xl font-bold">{doctor.name}</h2><p className="mt-1 text-sm text-primary">{doctor.speciality}</p>{connected?<><p className="mt-5 font-mono text-2xl font-bold">{String(Math.floor(seconds/60)).padStart(2,'0')}:{String(seconds%60).padStart(2,'0')}</p><p className="mt-2 text-xs text-muted-foreground">Demo doctor call · no real telephony connection</p><button onClick={onEnd} className="mt-7 w-full rounded-xl bg-destructive px-4 py-3 font-bold text-destructive-foreground">End call</button></>:<><p className="mt-5 text-sm text-muted-foreground">You can demonstrate accept, connected state, timer, and end call during the pitch.</p><div className="mt-7 grid grid-cols-2 gap-3"><button onClick={onDecline} className="rounded-xl border border-border px-4 py-3 font-bold">Decline</button><button onClick={onAccept} className="rounded-xl bg-primary px-4 py-3 font-bold text-primary-foreground">Accept</button></div></>}</div></div>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:ReactNode}){return <div className="fixed inset-0 z-[85] grid place-items-center bg-foreground/60 p-5"><div className="w-full max-w-md rounded-[2rem] bg-card p-6 shadow-2xl"><div className="flex items-center justify-between"><h2 className="font-display text-xl font-bold">{title}</h2><button onClick={onClose} className="grid size-9 place-items-center rounded-full bg-secondary"><X className="size-4"/></button></div><div className="mt-5">{children}</div></div></div>}
function BriefRow({label,value}:{label:string;value:string}){return <div className="rounded-2xl border border-border p-4"><p className="text-xs font-bold uppercase tracking-wider text-primary">{label}</p><p className="mt-1 text-sm font-semibold">{value}</p></div>}
function PageShell({eyebrow,title,description,children}:{eyebrow:string;title:string;description:string;children:ReactNode}){return <main className="mx-auto max-w-7xl px-5 py-12 pb-28 lg:px-8 lg:py-20"><div className="max-w-3xl"><p className="eyebrow">{eyebrow}</p><h1 className="mt-3 font-display text-4xl font-bold tracking-tight sm:text-6xl">{title}</h1><p className="mt-5 text-lg leading-8 text-muted-foreground">{description}</p></div><div className="mt-10">{children}</div></main>}
